import type { Href } from 'expo-router';

// Typed route files are regenerated by `expo start`; these helpers keep call sites stable either way.
export const postHref = (id: string) => `/post/${id}` as Href;
export const userHref = (uid: string) => `/user/${uid}` as Href;
export const settingsHref = '/settings' as Href;
